INSERT INTO feature VALUES('visual-language','editor','The visual language',NULL,'implemented','ordinary',NULL,'Five warrants, each with one colour name and one glyph, are the only hues a face paints. A renderer emits its output for a frame of named fields as rendering data, and twenty rules check that data: ink is data, no decoration, numerals with three significant digits and their unit at the head, labels that are field names, an absent datum drawn blank. The side view keeps every rule on each report a running hub sends.','surface-render-remote surface-tui','crates/surface-render-remote/src/visual.rs crates/surface-driver/tests/cli.rs::the_view_renders_a_corpus_source_in_the_visual_language',NULL,'#6287');
